Public Subroutine Importe(precio As Integer, cantidad As Integer) As Integer
  Return precio * cantidad;
EndSubroutine

Public Subroutine ConDescuento(monto As Integer) As Integer
  Return monto - monto Div 10;
EndSubroutine

Subroutine RedondearCentavos(monto As Integer) As Integer
  Return monto;
EndSubroutine

Import tienda.ventas;

Algorithm Principal
  Write ventas.ConDescuento(ventas.Importe(3, 7));
EndAlgorithm
